// src/orders/fetch-order.ts

export interface Order {
  id: string;
  status: "pending" | "paid" | "shipped" | "cancelled";
  totalCents: number;
  currency: string;
  // ...other fields the API actually returns
}

/** Error thrown when the orders API returns a non-2xx response. */
export class OrderApiError extends Error {
  readonly status: number;

  constructor(message: string, status: number, options?: { cause?: unknown }) {
    super(message, options);
    this.name = "OrderApiError";
    this.status = status;
  }
}

/** How long a single call is allowed to take before it is aborted (ms). */
const DEFAULT_TIMEOUT_MS = 5_000;

export interface FetchOrderOptions {
  /** Overrides the default timeout for this call. */
  timeoutMs?: number;
  /** Caller-supplied signal (e.g. the inbound request's signal) to cancel early. */
  signal?: AbortSignal;
  /** Overrides the default base URL, mainly useful in tests. */
  baseUrl?: string;
  /** Injected for tests; defaults to the global fetch. */
  fetchImpl?: typeof fetch;
}

function baseUrlFromEnv(): string {
  const url = process.env.ORDERS_API_URL;
  if (!url) {
    throw new Error("ORDERS_API_URL is not set");
  }
  return url;
}

export async function fetchOrder(
  id: string,
  options: FetchOrderOptions = {},
): Promise<Order> {
  // Validate the boundary input before it goes anywhere near the network.
  if (typeof id !== "string" || id.trim() === "") {
    throw new TypeError("fetchOrder: id must be a non-empty string");
  }

  const {
    timeoutMs = DEFAULT_TIMEOUT_MS,
    signal,
    baseUrl = baseUrlFromEnv(),
    fetchImpl = fetch,
  } = options;

  // Compose the caller's cancellation signal with our own timeout budget.
  // AbortSignal.any propagates whichever fires first (Node 20+).
  const timeoutSignal = AbortSignal.timeout(timeoutMs);
  const requestSignal = signal
    ? AbortSignal.any([signal, timeoutSignal])
    : timeoutSignal;

  const url = new URL(`/orders/${encodeURIComponent(id)}`, baseUrl);

  let response: Response;
  try {
    response = await fetchImpl(url, {
      method: "GET",
      headers: { accept: "application/json" },
      signal: requestSignal,
    });
  } catch (cause) {
    // Distinguish timeout/abort from a real network failure so callers can react.
    if (timeoutSignal.aborted && !(signal?.aborted ?? false)) {
      throw new Error(`fetchOrder: timed out after ${timeoutMs}ms (id=${id})`, {
        cause,
      });
    }
    if (signal?.aborted) {
      throw new Error(`fetchOrder: aborted by caller (id=${id})`, { cause });
    }
    throw new Error(`fetchOrder: request to orders API failed (id=${id})`, {
      cause,
    });
  }

  if (!response.ok) {
    throw new OrderApiError(
      `fetchOrder: orders API returned ${response.status} (id=${id})`,
      response.status,
    );
  }

  const body: unknown = await response.json();

  // Narrow the unknown response before it is treated as an Order.
  if (!isOrder(body)) {
    throw new Error(`fetchOrder: malformed response body (id=${id})`);
  }

  return body;
}

function isOrder(value: unknown): value is Order {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    typeof v.status === "string" &&
    typeof v.totalCents === "number" &&
    typeof v.currency === "string"
  );
}
```

Notes on the choices:

- **No hang, ever.** `AbortSignal.timeout(DEFAULT_TIMEOUT_MS)` bounds every call. If the caller passes its own signal (e.g. an inbound HTTP request's), `AbortSignal.any` ties the two together so whichever fires first aborts the request. This is the "thread an `AbortSignal` rather than a bespoke timeout" rule.
- **Timeout vs. caller-abort are distinguished** so the caller can tell "the dependency is slow" from "the client hung up" -- both are rethrown with the original error attached via `{ cause }`.
- **Input validated at the boundary.** The `id` check runs before any I/O, and the response body is narrowed from `unknown` with a type guard rather than cast to `Order`.
- **No new dependency.** Uses `fetch`, `URL`, `AbortSignal`, and a hand-written type guard. `AbortSignal.any`/`AbortSignal.timeout` need Node 20+ (they're stable there); if the project pins `engines.node` below 20, replace the `AbortSignal.any` composition with a manual `AbortController` that aborts on either the timeout or the caller's signal.
- **Errors are typed.** HTTP failures throw `OrderApiError` with the status; transport failures throw with a cause. Nothing is swallowed.

