import { z } from "zod";

const ORDER_API_URL = process.env.ORDERS_API_URL ?? "https://orders.internal";

// External input boundary: the API response is untrusted until parsed.
// Shape matches what the orders service actually returns; narrow with the
// schema instead of trusting an `any` cast.
const orderSchema = z.object({
  id: z.string(),
  status: z.enum(["pending", "paid", "shipped", "cancelled"]),
  totalCents: z.number().int().nonnegative(),
  currency: z.string().length(3),
  createdAt: z.string(),
});

export type Order = z.infer<typeof orderSchema>;

/**
 * Fetch a single order from the internal orders API.
 *
 * Bounded by a fixed timeout so a stalled orders service cannot hang the
 * request indefinitely. A caller-supplied AbortSignal (e.g. request-scoped)
 * is combined with the timeout so either can cancel the call.
 */
export async function fetchOrder(
  id: string,
  options: { signal?: AbortSignal; timeoutMs?: number } = {},
): Promise<Order> {
  const { signal, timeoutMs = 5_000 } = options;

  // Validate the external input (the id) at the point it enters the process.
  if (typeof id !== "string" || id.trim() === "") {
    throw new Error("fetchOrder: id must be a non-empty string");
  }

  // Combine the timeout with any caller signal so whichever fires first wins.
  const timeoutSignal = AbortSignal.timeout(timeoutMs);
  const combinedSignal = signal
    ? AbortSignal.any([signal, timeoutSignal])
    : timeoutSignal;

  const url = new URL(`/orders/${encodeURIComponent(id)}`, ORDER_API_URL);

  let response: Response;
  try {
    response = await fetch(url, {
      method: "GET",
      headers: { accept: "application/json" },
      signal: combinedSignal,
    });
  } catch (cause) {
    if (cause instanceof DOMException && cause.name === "TimeoutError") {
      throw new Error(
        `fetchOrder: orders API timed out after ${timeoutMs}ms for id=${id}`,
        { cause },
      );
    }
    if (cause instanceof DOMException && cause.name === "AbortError") {
      throw new Error(`fetchOrder: request aborted for id=${id}`, { cause });
    }
    throw new Error(`fetchOrder: request failed for id=${id}`, { cause });
  }

  if (response.status === 404) {
    throw new Error(`fetchOrder: order not found: ${id}`);
  }

  if (!response.ok) {
    throw new Error(
      `fetchOrder: orders API returned ${response.status} for id=${id}`,
    );
  }

  // Parse + validate the external response before it reaches business logic.
  let payload: unknown;
  try {
    payload = await response.json();
  } catch (cause) {
    throw new Error(
      `fetchOrder: orders API returned invalid JSON for id=${id}`,
      { cause },
    );
  }

  const parsed = orderSchema.safeParse(payload);
  if (!parsed.success) {
    throw new Error(
      `fetchOrder: orders API returned unexpected shape for id=${id}`,
      { cause: parsed.error },
    );
  }

  return parsed.data;
}
```

Key points, mapped to the rules this skill draws from:

- **Bound on the hang.** The core of the request is `AbortSignal.timeout(timeoutMs)` with a 5s default, so a slow orders API aborts the underlying `fetch` instead of hanging forever. This is the whole point of the ask.
- **Cancellation is composable.** When the caller passes its own `signal` (e.g. the inbound request's signal), `AbortSignal.any([...])` combines them, so either a client disconnect or the timeout cancels the call — rather than adding a bespoke timeout mechanism alongside the caller's.
- **Validation at the boundary.** The `id` is checked on entry, and the untrusted API response is parsed with a zod schema (`unknown` → narrowed) before it's returned as a typed `Order`. No `any`.
- **Errors carry context and cause.** Timeout, abort, non-OK status, bad JSON, and shape mismatches each throw an `Error` naming the operation and the identifier, chaining the lower-level error via `{ cause }` — not swallowed with a `console.log`.
- **Async-only, no floating promises.** Uses `fetch`/`response.json()` (async); every awaited promise is awaited. No sync I/O on the request path.

