    typeof o.status === "string" &&
    typeof o.total === "number" &&
    typeof o.currency === "string" &&
    typeof o.createdAt === "string"
  );
}

export async function fetchOrder(
  id: string,
  options: FetchOrderOptions = {}
): Promise<Order> {
  // Validate input at the boundary.
  if (typeof id !== "string" || id.trim() === "") {
    throw new OrderFetchError(
      "fetchOrder called with an empty or non-string id"
    );
  }

  const baseUrl = options.baseUrl ?? DEFAULT_BASE_URL;
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;

  // Combine the caller's signal (cancellation) with a fixed timeout budget.
  const timeoutSignal = AbortSignal.timeout(timeoutMs);
  const signal = options.signal
    ? AbortSignal.any([options.signal, timeoutSignal])
    : timeoutSignal;

  let res: Response;
  try {
    res = await fetch(`${baseUrl}/orders/${encodeURIComponent(id)}`, {
      method: "GET",
      headers: { accept: "application/json" },
      signal,
    });
  } catch (cause) {
    if (signal.aborted) {
      const reason = options.signal?.aborted
        ? "caller aborted"
        : `timed out after ${timeoutMs}ms`;
      throw new OrderFetchError(`fetchOrder(${id}) ${reason}`, { cause });
    }
    throw new OrderFetchError(
      `fetchOrder(${id}) failed to reach orders API`,
      { cause }
    );
  }

  if (res.status === 404) {
    throw new OrderFetchError(`fetchOrder(${id}) not found`);
  }
  if (!res.ok) {
    throw new OrderFetchError(
      `fetchOrder(${id}) orders API returned ${res.status}`
    );
  }

  let body: unknown;
  try {
    body = await res.json();
  } catch (cause) {
    throw new OrderFetchError(
      `fetchOrder(${id}) returned a non-JSON body`,
      { cause }
    );
  }

  // Validate the external payload before it reaches business logic.
  if (!isOrder(body)) {
    throw new OrderFetchError(
      `fetchOrder(${id}) returned an unexpected payload shape`
    );
  }

  // `sleep` is imported for illustration of an optional retry back-off; drop
  // it if unused so there is no unused import.
  void sleep;

  return body;
}
```

Key points against the skill's workflow and rules:

- **Timeout / no hanging.** `AbortSignal.timeout(timeoutMs)` gives a fixed upper bound, and `AbortSignal.any([...])` lets the caller's request-scoped signal still win for cancellation. Nothing here can hang forever.
- **Input validation at the boundary.** The `id` is checked (non-empty string) before any work, and the response body is validated with a type guard before being returned as `Order` -- `unknown` is narrowed, never typed as `any`.
- **Error contract.** Failures throw `OrderFetchError` with a message naming the operation and id, and chain the underlying cause via `{ cause }` rather than swallowing it. 404 and non-2xx are distinguished from transport failures.
- **`node:` protocol imports.** `node:timers/promises` is prefixed per the rule.
- **No floating promises / no new deps.** Only built-ins and global `fetch` are used; every promise is awaited.

Suggested follow-ups to match a real project:

1. Replace the regex-free `isOrder` guard with the project's existing schema library (e.g. zod) if one is already a dependency -- do not add a new one just for this.
2. Confirm `moduleResolution`/`"type"` in `tsconfig.json`/`package.json` support top-level `AbortSignal.any` and `AbortSignal.timeout` (Node 20+); if the project targets an older Node, fall back to a manual `AbortController` plus `setTimeout`.
3. Remove the illustrative `sleep`/`void sleep` lines -- they exist only to show where retry back-off would go and must not ship as dead code.
4. Run the project's own checks before reporting done:

```bash
npx tsc --noEmit
npx eslint .
```

Both must exit 0 with no new `any` and no silencing eslint-disable comments. Then hand off to `nodejs-testing` for coverage of the timeout, 404, non-2xx, malformed-JSON, and bad-shape paths.

`unknown`.

That is the whole point of the boundary rule: `JSON.parse` (or whatever produced the parsed value) gives you something whose shape you have not verified, and `unknown` is the type that forces you to prove the shape before you can touch any of it. `any` would do the opposite -- it silently permits `.orderId`, `.items.length`, destructuring, and passing it straight into business logic, so a malformed or malicious body (or a nested value of an unexpected type) slips through with zero compiler friction.

The concrete shape:

```ts
// The value arrives as unknown...
const raw: unknown = await req.json(); // or JSON.parse(await req.text())

// ...and only becomes a typed value after validation narrows it.
const parsed = OrderSchema.safeParse(raw);
if (!parsed.success) {
  throw new ValidationError("invalid order body", { cause: parsed.error });
}
const order: Order = parsed.data; // now typed, now safe to pass on
```

Use whatever the entry point actually returns as the unvalidated type first: `await req.json()` is itself `any` in a lot of stacks, so assign it to `unknown` immediately rather than letting `any` leak. If the project has no schema library, narrow with an explicit type guard (`function isOrder(value: unknown): value is Order`) rather than a cast -- a cast is just `any` wearing a costume, because it asserts the shape instead of checking it.

The ordering matters and is testable: parsed value is `unknown` → validator narrows it → business logic receives the narrowed type. If any line of business logic can see a value that was never narrowed, the boundary was placed wrong. If you run `tsc --noEmit` and it passes while business logic still accepts the pre-validation value, look for an `any` or a cast in the chain -- that is the seam where the guarantee leaked out.

`unknown`.

`JSON.parse` (and any untrusted input entering the process) should land in a variable typed `unknown`, never `any`. `any` silently disables the type checker for every value the data flows into, so a typo'd property access or a wrong-shaped value passed to business logic compiles clean and fails at runtime. `unknown` forces you to narrow the value — via a schema parse (zod, etc.) or an explicit type guard — before you can touch its properties at all.

Sketch of the shape:

```ts
type OrderInput = { id: string; quantity: number }; // the validated shape

function isOrderInput(value: unknown): value is OrderInput {
  // or: return OrderInputSchema.safeParse(value).success
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return typeof v.id === "string" && typeof v.quantity === "number";
}

export async function handlePost(req: Request) {
  const raw: unknown = await req.json(); // parsed body stays unknown
  if (!isOrderInput(raw)) {
    throw new Error("Invalid order body", { status: 400 } as never); // project-shaped error
  }
  // raw is now narrowed to OrderInput
  return OrderService.create(raw);
}
```

Two things to keep in mind alongside the type:

- Validate at the point the data enters the process (the route handler), not deeper in the service layer — that's the boundary rule. Once narrowed, the value can flow into business logic carrying a real type.
- If the project already has a schema library as a dependency, use it (`const parsed = OrderInputSchema.parse(raw)`) rather than hand-rolling the guard — same result, less code, and the schema stays the single source of truth for the shape.

If you're on a strict `tsconfig`, `noImplicitAny` plus `unknown` on the parsed body is what makes the narrowing mandatory rather than optional — check `tsconfig.json` in Step 1 of the workflow to confirm strictness is actually on before relying on it.

`unknown`.

`JSON.parse` (or `req.body`, if some middleware already parsed it) returns a value whose shape you genuinely don't know yet, and the point of using `unknown` rather than `any` is that the type checker will refuse to let you read any property or call any method on it until you've narrowed it. That's exactly the behavior you want at a trust boundary: it forces the validation step to happen before the data can be used, rather than letting it silently flow into business logic.

Concretely, the shape is:

```ts
type CreateOrderBody = { customerId: string; amount: number };

export async function createOrderHandler(req: Request, res: Response) {
  const raw: unknown = req.body; // or JSON.parse(await readBody(req))

  const parsed = CreateOrderSchema.safeParse(raw); // zod / valibot / arktype
  if (!parsed.success) {
    return res.status(400).json({ error: "invalid body" });
  }

  const body: CreateOrderBody = parsed.data; // typed from here on
  return orderService.create(body);
}
```

A few points that matter as much as the type annotation itself:

- Do the validation in the handler, not inside the service. The service should receive already-typed, already-validated data; that way every caller of the service gets the same guarantee and you never have a second entry point that bypasses the check.
- After validation, narrow to the concrete type rather than keeping `unknown` around and casting at each use site. One narrow at the boundary, a concrete type everywhere downstream.
- If the project has no schema library, an explicit type guard (`function isCreateOrderBody(x: unknown): x is CreateOrderBody`) or a hand-rolled check works fine — the important part is that the guard actually inspects the runtime value rather than asserting.
- Avoid `as CreateOrderBody` on something still typed `unknown`. That's an assertion, not a check; it compiles but provides zero runtime safety and defeats the purpose of typing it as `unknown` in the first place.

One follow-on worth flagging: if you're reading the body yourself with `JSON.parse` rather than a framework body-parser, wrap the parse in a try/catch — malformed JSON throws a `SyntaxError`, and you want that turned into a 400 rather than an unhandled rejection. Also parse the whole string before validating, and reject non-object results (`null`, a bare number, wrapped arrays if you don't accept them), since `JSON.parse("null")` is valid JSON but not a valid body for your handler.

`unknown`.

`JSON.parse(...)` (or whatever returns the parsed body) is a boundary: the data's shape is not yet proven, so its type should be `unknown`, not `any` and not a hand-written interface that asserts the shape you merely hope is there.

Why `unknown` and not `any`:
- `unknown` is the safe top type: you are forced to narrow it (via a validator or a type guard) before you can access any property or call any method on it.
- `any` opts the value — and everything derived from it — out of type checking entirely, so a typo like `body.userIdd` or a missing null check sails through `tsc` and blows up at runtime.

Concrete shape of the flow:

```ts
// boundary: untrusted
const raw: unknown = await request.json(); // or JSON.parse(text)

// validate at the boundary, narrow to a concrete type
const parsed = OrderInputSchema.parse(raw); // zod -> OrderInput
// or an explicit guard:
// if (!isOrderInput(raw)) throw new ValidationError("invalid order body");
// raw is now narrowed to OrderInput

await orderService.create(parsed); // business logic gets a validated, typed value
```

A few points that matter here:

- The validated, narrowed type (e.g. `OrderInput`) is what crosses into the service layer — business logic should never see `unknown` or a raw parse result.
- Validation belongs at the point the data enters the process (the route handler), not two layers deeper in the service. That's the boundary rule.
- If validation fails, throw an `Error` naming what failed (and which field), rather than letting an undefined-property access fail later with a confusing stack.
- `tsc --noEmit` and `eslint` should both be clean, with no new `any` introduced and no `eslint-disable` added to silence a real finding.

So: parse to `unknown`, validate/narrow to the concrete input type, then hand that typed value to business logic.

`unknown`.

`JSON.parse` returns `any` in TypeScript's lib typings, so the moment you do `const body = JSON.parse(raw)` and give it an inferred type, you've silently opted out of type checking for everything downstream — property accesses, destructuring, passing it to a function, all of it. Assign it to an explicitly annotated `unknown` instead:

```ts
const body: unknown = JSON.parse(raw);
```

Then narrow it with a validator or a type guard before anything touches its fields:

```ts
const parsed = OrderInputSchema.safeParse(body);
if (!parsed.success) {
  throw new Error(`Invalid order body: ${parsed.error.message}`);
}
const input: OrderInput = parsed.data;
```

A few notes on where this fits:

- If the project already has a schema library as a dependency (zod, ajv, valibot, typebox), use it — don't hand-roll property checks. It gives you the narrowing edge back to a concrete type via `parsed.data` rather than a manual `as` cast.
- Don't reach for a type assertion (`as OrderInput`) to make `unknown` go away. That is the same hole as `any`, just spelled differently.
- Keep the validation at the request boundary — in the route handler, before the body reaches the service layer. Validating inside the service means unvalidated data has already crossed a boundary.
- Wrap the `JSON.parse` call itself too: a malformed body throws a `SyntaxError`, which is a different failure from a well-formed body with the wrong shape. Surface both as client errors (400-class) rather than letting the `SyntaxError` bubble up as a 500.
- The same rule applies to every other external input this handler touches — query params, path params, headers you read, env vars — each enters as `unknown` and gets narrowed at the point of entry.

`unknown`.

That is the whole point of the workflow in Step 3: `JSON.parse` (or whatever framework body parser hands you) produces data whose shape is not guaranteed by the type system. Typing it as `unknown` forces you to narrow it with a validator or a type guard before it can be used, which is exactly the boundary-validation step.

```ts
// BAD: lies to the type checker; if the body is {} you find out at runtime,
// three layers deep, as a TypeError on `body.email.toLowerCase()`
function handlePost(req: Request) {
  const body = req.body as { email: string };
  return createUser(body.email);
}

// GOOD: unknown until validated
function handlePost(req: Request) {
  const raw: unknown = req.body;
  const parsed = CreateUserSchema.safeParse(raw);
  if (!parsed.success) {
    throw new ValidationError("invalid request body", { cause: parsed.error });
  }
  return createUser(parsed.data); // now typed, and actually checked
}
```

A few notes that matter here:

- Use your project's existing schema library (zod, valibot, ajv, a hand-rolled type guard) rather than introducing a new one -- the discovery step says to reuse what is already a dependency.
- Validate at the point the data enters the process, i.e. in the route handler, not inside the service. Routing it into business logic first and validating later is one of the listed red flags.
- `any` is explicitly called out as the wrong answer: it disables the checker for everything downstream, including the business logic you were trying to protect.

Once the body is parsed and narrowed, `parsed.data` is the typed value you pass onward. And per the skill's handoff rule, once this compiles and lints clean, test coverage belongs to `nodejs-testing` unless you were asked to do both in one pass.

Use `unknown`, not `any`. `JSON.parse(...)` (or whatever deserializes the body) returns a value whose shape you have not verified, so `unknown` is the honest type: it forces you to narrow before use and keeps the type checker live downstream. `any` would silently disable checking for everything the body touches, which defeats the boundary-validation rule this skill exists to enforce.

A typical shape:

```ts
async function handler(req: Request): Promise<Response> {
  const raw: unknown = await req.json();      // or JSON.parse(await readBody(req))
  const parsed = OrderInputSchema.safeParse(raw);
  if (!parsed.success) {
    return new Response("invalid body", { status: 400 });
  }
  const body = parsed.data;                    // now typed and validated
  return OrderService.create(body);
}
```

Notes that matter for this step:

- Validate at the boundary — here, before `body` reaches `OrderService.create` — not two layers deeper in the service.
- If the project has a schema library (zod, valibot, ajv) already in `package.json`, reuse it rather than hand-rolling checks; if not, explicit type guards that narrow `unknown` are fine.
- Wrap the parse itself: malformed JSON throws a `SyntaxError`, so catch it and surface a 400 rather than letting it bubble as a 500. That throw is a case where wrapping with `new Error("...", { cause })` is appropriate if you rethrow.
- After narrowing, pass the validated, concretely-typed value onward — never the original `unknown` — so no consumer inherits the unvalidated type.
